import { readFile, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const projectRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const sourceFiles = [
  'js/config.js',
  'js/random.js',
  'js/map.js',
  'js/game-engine.js',
  'js/renderer.js',
  'js/input.js',
  'js/screens.js',
  'js/main.js'
];

function removeImports(source) {
  const output = [];
  let insideImport = false;

  for (const line of source.split(/\r?\n/)) {
    if (!insideImport && /^\s*import\b/.test(line)) {
      insideImport = !/;\s*$/.test(line);
      continue;
    }

    if (insideImport) {
      if (/;\s*$/.test(line)) {
        insideImport = false;
      }
      continue;
    }

    output.push(line);
  }

  if (insideImport) {
    throw new Error('Unterminated import statement');
  }

  return output.join('\n');
}

function convertModuleToClassic(source) {
  return removeImports(source).replace(
    /\bexport\s+(?=(?:const|class|function)\b)/g,
    ''
  );
}

const sections = [];

for (const relativePath of sourceFiles) {
  const source = await readFile(resolve(projectRoot, relativePath), 'utf8');
  sections.push(`\n/* ${relativePath} */\n${convertModuleToClassic(source)}`);
}

const bundle = `/* Generated by scripts/build-bundle.mjs. Do not edit directly. */
(() => {
'use strict';
${sections.join('\n')}
})();
`;

await writeFile(resolve(projectRoot, 'js/game.bundle.js'), bundle, 'utf8');
